package org.mockito.internal.creation.instance;

import java.io.*;
import java.lang.reflect.Constructor;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.creation.instance.ConstructorInstantiator;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ConstructorInstantiator.newInstance
 */
public class ConstructorInstantiator_newInstance_TriageGen2Test {

    /**
     * Test class to allow spying on the abstract/protected methods 
     * required to satisfy the logic of newInstance.
     */
    private static class TestConstructorInstantiator extends ConstructorInstantiator {

        public TestConstructorInstantiator(Object outerClassInstance) {
            super(outerClassInstance);
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T noArgConstructor(Class<T> cls) {
            // Mock implementation for testing
            return (T) cls.getDeclaredConstructor().newInstance();
        }

        @Override
        @SuppressWarnings("unchecked")
        public <T> T withOuterClass(Class<T> cls) {
            // Mock implementation for testing
            try {
                return (T) cls.getDeclaredConstructor(Object.class).newInstance(getOuterClassInstance());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
    }

    // Helper classes for instantiation
    public static class SimpleClass {
        public SimpleClass() {}
    }

    public static class OuterClass {
        public SimpleClass() {}
        public SimpleClass(Object outer) {}
    }

    @Test
    public void testNewInstance_WhenOuterClassInstanceIsNull_CallsNoArgConstructor() throws Exception {
        // Arrange
        // We use a spy on a concrete implementation to verify which branch is taken
        TestConstructorInstantiator instantiator = spy(new TestConstructorInstantiator(null));
        Class<SimpleClass> cls = SimpleClass.class;

        // Act
        SimpleClass result = instantiator.newInstance(cls);

        // Assert
        assertEquals(cls, result.getClass());
        // Verify branch: outerClassInstance == null -> calls noArgConstructor
        org.mockito.Mockito.verify(instantiator).noArgConstructor(cls);
        org.mockito.Mockito.verify(instantiator, org.mockito.Mockito.never()).withOuterClass(cls);
    }

    @Test
    public void testNewInstance_WhenOuterClassInstanceIsNotNull_CallsWithOuterClass() throws Exception {
        // Arrange
        Object outerInstance = new Object();
        TestConstructorInstantiator instantiator = spy(new TestConstructorInstantiator(outerInstance));

        // To make withOuterClass work in our Test implementation, 
        // we need a class that accepts the outer instance in its constructor.
        // We'll use a specifically designed class for this branch.
        class InnerWithOuter {
            Object outer;
            public InnerWithOuter(Object outer) { this.outer = outer; }
        }
        Class<InnerWithOuter> cls = InnerWithOuter.class;

        // Act
        InnerWithOuter result = instantiator.newInstance(cls);

        // Assert
        assertEquals(cls, result.getClass());
        assertEquals(outerInstance, result.outer);
        // Verify branch: outerClassInstance != null -> calls withOuterClass
        org.mockito.Mockito.verify(instantiator).withOuterClass(cls);
        org.mockito.Mockito.verify(instantiator, org.mockito.Mockito.never()).noArgConstructor(cls);
    }
}
